// Reversible column packing of PBCBIN01 records, with no mathematical changes.
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using V=std::vector<unsigned char>;
static void pu(uint64_t n){while(n>=128){std::cout.put(char((n&127)|128));n>>=7;}std::cout.put(char(n));}
static uint64_t gu(V*save=nullptr){uint64_t n=0;int s=0;for(;;){int c=std::cin.get();if(c<0||s>63)throw std::runtime_error("invalid varint");if(save)save->push_back(c);n|=uint64_t(c&127)<<s;if(c<128)return n;s+=7;}}
static void take(V&v,uint64_t n){if(n>1000000000)throw std::runtime_error("length limit");size_t a=v.size();v.resize(a+n);if(n&&!std::cin.read((char*)v.data()+a,n))throw std::runtime_error("truncated input");}
static uint64_t vu(const V&v,size_t&pos,V*save=nullptr){uint64_t n=0;int s=0;for(;;){if(pos>=v.size()||s>63)throw std::runtime_error("bad channel varint");int c=v[pos++];if(save)save->push_back(c);n|=uint64_t(c&127)<<s;if(c<128)return n;s+=7;}}
static void copy(V&out,const V&v,size_t&pos,uint64_t n){if(n>v.size()-pos)throw std::runtime_error("channel truncation");out.insert(out.end(),v.begin()+pos,v.begin()+pos+n);pos+=n;}
static void pack(size_t block){char magic[8];if(!std::cin.read(magic,8)||std::string(magic,8)!="PBCBIN01")throw std::runtime_error("expected PBCBIN01");V header(magic,magic+8);uint64_t len=gu(&header);take(header,len);std::cout.write("PBCSHF02",8);pu(header.size());std::cout.write((char*)header.data(),header.size());uint64_t total=0;
 for(;;){V ch[8];size_t count=0;for(;count<block;++count){int op=std::cin.get();if(op<0)break;if(op>3)throw std::runtime_error("bad opcode");ch[0].push_back(op);if(op==0){auto n=gu(&ch[6]);take(ch[7],n);}else{gu(&ch[1]);gu(&ch[2]);if(op==1)gu(&ch[3]);if(op!=3){int t=std::cin.get();if(t<0||t>5)throw std::runtime_error("coefficient tag");ch[4].push_back(t);auto n=gu(&ch[4]);take(ch[5],n);}}}if(!count)break;pu(count);for(auto&v:ch)pu(v.size());for(auto&v:ch)if(!v.empty())std::cout.write((char*)v.data(),v.size());total+=count;}pu(0);std::cerr<<"packed records="<<total<<" block="<<block<<'\n';
}
static void unpack(){char magic[8];if(!std::cin.read(magic,8)||std::string(magic,8)!="PBCSHF02")throw std::runtime_error("expected PBCSHF02");V header;take(header,gu());std::cout.write((char*)header.data(),header.size());uint64_t total=0;for(;;){auto count=gu();if(!count)break;uint64_t lengths[8];for(auto&n:lengths)n=gu();V ch[8];size_t pos[8]={};for(int i=0;i<8;++i)take(ch[i],lengths[i]);if(ch[0].size()!=count)throw std::runtime_error("opcode count");V out;for(uint64_t i=0;i<count;++i){int op=ch[0][i];out.push_back(op);if(op==0){auto n=vu(ch[6],pos[6],&out);copy(out,ch[7],pos[7],n);}else{if(op>3)throw std::runtime_error("bad opcode");vu(ch[1],pos[1],&out);vu(ch[2],pos[2],&out);if(op==1)vu(ch[3],pos[3],&out);if(op!=3){copy(out,ch[4],pos[4],1);auto n=vu(ch[4],pos[4],&out);copy(out,ch[5],pos[5],n);}}}for(int i=1;i<8;++i)if(pos[i]!=ch[i].size())throw std::runtime_error("unconsumed channel");std::cout.write((char*)out.data(),out.size());total+=count;}if(std::cin.peek()!=EOF)throw std::runtime_error("trailing bytes");std::cerr<<"unpacked records="<<total<<'\n';}
int main(int argc,char**argv){try{std::ios::sync_with_stdio(false);std::cin.tie(nullptr);if(argc<2)throw std::runtime_error("usage pack [block] | unpack");if(std::string(argv[1])=="pack")pack(argc>2?std::stoull(argv[2]):262144);else if(std::string(argv[1])=="unpack")unpack();else throw std::runtime_error("bad mode");std::cout.flush();if(!std::cout)throw std::runtime_error("output error");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
